// Extract alert and determine incident state
const body = $input.item.json.body;
const alert = body.alert || $input.item.json;

const alertName = alert.alertName || alert.labels?.alertname;
const fingerprint = alert.fingerprint || '';
const status = alert.status || 'unknown';
const severity = alert.severity || alert.labels?.severity || 'unknown';

// Generate incident ID based on alert fingerprint or name
const incidentId = `inc-${fingerprint.substring(0, 8) || Date.now()}`;

// Determine if this is a new incident or update
const isFiring = status === 'firing';
const isResolved = status === 'resolved';

return {
  json: {
    incidentId,
    alert,
    alertName,
    fingerprint,
    status,
    severity,
    isFiring,
    isResolved,
    processedAt: new Date().toISOString(),
    cluster: alert.cluster || alert.labels?.cluster || 'unknown',
    namespace: alert.namespace || alert.labels?.namespace || '',
    summary: alert.summary || alert.annotations?.summary || '',
    description: alert.description || alert.annotations?.description || ''
  }
};

// Create new incident record
const alert = $input.item.json;

const incident = {
  incident_id: alert.incidentId,
  fingerprint: alert.fingerprint,
  alert_name: alert.alertName,
  severity: alert.severity,
  cluster: alert.cluster,
  namespace: alert.namespace,

  // Timeline
  fired_at: alert.alert.startsAt || new Date().toISOString(),
  acknowledged_at: null,
  resolved_at: null,

  // Status
  status: 'active',
  state: 'firing',

  // Details
  summary: alert.summary,
  description: alert.description,
  labels: alert.alert.labels || {},
  annotations: alert.alert.annotations || {},

  // Metadata
  created_at: new Date().toISOString(),
  updated_at: new Date().toISOString(),

  // Related alerts (will be aggregated)
  related_alerts: [{
    fingerprint: alert.fingerprint,
    fired_at: alert.alert.startsAt,
    summary: alert.summary
  }],

  // Metrics
  alert_count: 1,
  mttr_seconds: null
};

return {
  json: {
    ...alert,
    incident
  }
};

// Update existing incident with resolved status
const alert = $input.item.json;

// In a real implementation, you would:
// 1. Read existing incident from storage
// 2. Calculate MTTR
// 3. Update status

// For this example, we'll create the resolved update
const now = new Date();
const firedAt = new Date(alert.alert.startsAt || now);
const mttrSeconds = Math.floor((now - firedAt) / 1000);

const incidentUpdate = {
  incident_id: alert.incidentId,
  fingerprint: alert.fingerprint,

  // Timeline
  resolved_at: now.toISOString(),

  // Status
  status: 'resolved',
  state: 'resolved',

  // Metrics
  mttr_seconds: mttrSeconds,
  mttr_human: formatDuration(mttrSeconds),

  // Metadata
  updated_at: now.toISOString()
};

function formatDuration(seconds) {
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const secs = seconds % 60;

  if (hours > 0) {
    return `${hours}h ${minutes}m ${secs}s`;
  } else if (minutes > 0) {
    return `${minutes}m ${secs}s`;
  } else {
    return `${secs}s`;
  }
}

return {
  json: {
    ...alert,
    incidentUpdate
  }
};

// Aggregate related alerts into single incident
// This would check if similar alerts should be grouped

const alert = $input.item.json;
const alertName = alert.alertName;
const namespace = alert.namespace;
const cluster = alert.cluster;

// In production, query existing incidents with similar characteristics
// For now, we'll create a grouping key
const groupingKey = `${cluster}:${namespace}:${alertName}`;

return {
  json: {
    ...alert,
    groupingKey,
    shouldAggregate: true // In production, check if existing incident matches
  }
};

// Generate weekly incident summary
const incidents = $input.item.json.incidents || [];

const totalIncidents = incidents.length;
const criticalIncidents = incidents.filter(i => i.severity === 'critical').length;
const resolvedIncidents = incidents.filter(i => i.status === 'resolved').length;
const activeIncidents = incidents.filter(i => i.status === 'active').length;

// Calculate average MTTR for resolved incidents
const resolvedWithMttr = incidents.filter(i => i.mttr_seconds !== null);
const avgMttr = resolvedWithMttr.length > 0
  ? resolvedWithMttr.reduce((sum, i) => sum + i.mttr_seconds, 0) / resolvedWithMttr.length
  : 0;

function formatDuration(seconds) {
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  return hours > 0 ? `${hours}h ${minutes}m` : `${minutes}m`;
}

// Group by alert name
const byAlertName = {};
incidents.forEach(inc => {
  const name = inc.alert_name;
  if (!byAlertName[name]) {
    byAlertName[name] = { count: 0, critical: 0, resolved: 0 };
  }
  byAlertName[name].count++;
  if (inc.severity === 'critical') byAlertName[name].critical++;
  if (inc.status === 'resolved') byAlertName[name].resolved++;
});

// Create summary report
const summary = {
  period: 'Last 7 days',
  generated_at: new Date().toISOString(),

  overview: {
    total_incidents: totalIncidents,
    critical_incidents: criticalIncidents,
    active_incidents: activeIncidents,
    resolved_incidents: resolvedIncidents,
    resolution_rate: totalIncidents > 0 ? (resolvedIncidents / totalIncidents * 100).toFixed(1) + '%' : 'N/A'
  },

  performance: {
    avg_mttr_seconds: Math.floor(avgMttr),
    avg_mttr_human: formatDuration(Math.floor(avgMttr))
  },

  by_alert_type: byAlertName,

  top_incidents: incidents
    .sort((a, b) => (b.alert_count || 0) - (a.alert_count || 0))
    .slice(0, 5)
    .map(inc => ({
      incident_id: inc.incident_id,
      alert_name: inc.alert_name,
      severity: inc.severity,
      status: inc.status,
      alert_count: inc.alert_count || 1,
      mttr: inc.mttr_human || 'Active'
    }))
};

// Format Slack message
const slackMessage = {
  blocks: [
    {
      type: "header",
      text: {
        type: "plain_text",
        text: "Weekly Incident Summary Report",
        emoji: true
      }
    },
    {
      type: "section",
      text: {
        type: "mrkdwn",
        text: `*Period:* ${summary.period}\n*Generated:* ${new Date().toLocaleString()}`
      }
    },
    {
      type: "divider"
    },
    {
      type: "section",
      fields: [
        {
          type: "mrkdwn",
          text: `*Total Incidents:*\n${summary.overview.total_incidents}`
        },
        {
          type: "mrkdwn",
          text: `*Critical:*\n${summary.overview.critical_incidents}`
        },
        {
          type: "mrkdwn",
          text: `*Resolved:*\n${summary.overview.resolved_incidents}`
        },
        {
          type: "mrkdwn",
          text: `*Active:*\n${summary.overview.active_incidents}`
        },
        {
          type: "mrkdwn",
          text: `*Resolution Rate:*\n${summary.overview.resolution_rate}`
        },
        {
          type: "mrkdwn",
          text: `*Avg MTTR:*\n${summary.performance.avg_mttr_human}`
        }
      ]
    },
    {
      type: "divider"
    },
    {
      type: "section",
      text: {
        type: "mrkdwn",
        text: "*Top Incidents:*\n" + summary.top_incidents.map((inc, idx) => 
          `${idx + 1}. ${inc.alert_name} (${inc.severity}) - ${inc.alert_count} alerts - MTTR: ${inc.mttr}`
        ).join('\n')
      }
    }
  ]
};

return {
  json: {
    summary,
    slackMessage
  }
};
